CREATE OR REPLACE FUNCTION public.post_comment_page(p_post uuid, p_limit integer DEFAULT 50, p_before_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, author_id uuid, body text, created_at timestamp with time zone, author_display_name text, author_username text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select c.id, c.author_id, c.body, c.created_at, p.display_name, p.username
  from public.activity_comments c
  left join public.profiles p on p.id = c.author_id
  where c.post_id = p_post
    and (p_before_at is null or p_before_id is null
         or (c.created_at, c.id) < (p_before_at, p_before_id))
  order by c.created_at desc, c.id desc
  limit least(greatest(coalesce(p_limit, 50), 1), 101);
$function$;

